INSERT INTO questions (content, type, difficulty, role_tag, company_tag, expected_answer, scoring_rubric) VALUES
('What is the difference between a process and a thread?', 'DSA', 'EASY', 'SDE', 'MNC', 'A process is an independent execution unit with its own memory space, while a thread is a subset of a process that shares memory with other threads in the same process.', '{"keywords": ["memory space", "subset", "parallelism", "context switching"], "concepts": ["Operating Systems", "Concurrency"], "max_score": 100}'),
('Tell me about a time you had a conflict with a teammate.', 'BEHAVIORAL', 'MEDIUM', 'ALL', 'FAANG', 'Describe the specific situation, the task involved, the actions you took to resolve the conflict (communication, empathy, compromise), and the positive outcome.', '{"keywords": ["communication", "resolution", "empathy", "outcome"], "concepts": ["STAR method", "Conflict Resolution"], "max_score": 100}'),
('Design a URL shortener like Bitly.', 'SYSTEM_DESIGN', 'HARD', 'SDE', 'FAANG', 'Explain the high-level architecture: API gateway, load balancer, application servers, hashing algorithm (Base62), database selection (NoSQL for scalability), and caching (Redis).', '{"keywords": ["Base62", "scalability", "NoSQL", "caching", "hashing"], "concepts": ["System Design", "Microservices"], "max_score": 100}'),
('Explain the concept of Big O notation.', 'DSA', 'EASY', 'SDE', 'ALL', 'Big O notation describes the upper bound of an algorithm''s time or space complexity in terms of the input size N.', '{"keywords": ["upper bound", "complexity", "input size", "asymptotic"], "concepts": ["Algorithm Analysis"], "max_score": 100}'),
('What are your greatest strengths and weaknesses?', 'HR', 'EASY', 'ALL', 'ALL', 'Mention strengths relevant to the job (e.g., fast learner, problem solver) and a genuine weakness you are actively working on improving.', '{"keywords": ["self-awareness", "improvement", "relevance"], "concepts": ["HR Interview"], "max_score": 100}'),
('How does a Hash Map work internally in Java?', 'DSA', 'MEDIUM', 'SDE', 'MNC', 'A Hash Map uses an array of buckets. It computes an index using the key''s hashCode. Collisions are handled using linked lists or red-black trees (Java 8+).', '{"keywords": ["buckets", "hashCode", "collisions", "linked list", "red-black tree"], "concepts": ["Data Structures"], "max_score": 100}'),
('Explain the CAP theorem.', 'SYSTEM_DESIGN', 'MEDIUM', 'SDE', 'STARTUP', 'CAP stands for Consistency, Availability, and Partition Tolerance. A distributed system can only provide two out of these three guarantees at the same time.', '{"keywords": ["Consistency", "Availability", "Partition Tolerance", "distributed systems"], "concepts": ["System Design"], "max_score": 100}'),
('Why do you want to join our company?', 'HR', 'EASY', 'ALL', 'ALL', 'Show you researched the company values, products, and mission. Relate your career goals to how the company helps you achieve them.', '{"keywords": ["research", "alignment", "values", "mission"], "concepts": ["HR Interview"], "max_score": 100}'),
('What is the difference between TCP and UDP?', 'DSA', 'EASY', 'DEVOPS', 'MNC', 'TCP is connection-oriented and reliable, ensuring data delivery in order. UDP is connectionless and fast but doesn''t guarantee delivery.', '{"keywords": ["connection-oriented", "reliable", "connectionless", "handshake"], "concepts": ["Networking"], "max_score": 100}'),
('Implement a function to find the middle element of a linked list in one pass.', 'DSA', 'MEDIUM', 'SDE', 'ALL', 'Use two pointers: a slow pointer moving one step at a time and a fast pointer moving two steps at a time. When fast reaches the end, slow is at the middle.', '{"keywords": ["two pointers", "slow pointer", "fast pointer", "single pass"], "concepts": ["Algorithms", "Linked List"], "max_score": 100}'),
('How would you design a rate limiter?', 'SYSTEM_DESIGN', 'HARD', 'SDE', 'FAANG', 'Discuss algorithms like Token Bucket, Leaky Bucket, or Fixed Window Counter. Mention distributed rate limiting using Redis.', '{"keywords": ["Token Bucket", "Leaky Bucket", "Redis", "Throttling"], "concepts": ["System Design", "Scalability"], "max_score": 100}'),
('Describe a difficult technical challenge you faced and how you overcame it.', 'BEHAVIORAL', 'HARD', 'ALL', 'FAANG', 'Explain the technical problem, why it was hard, the steps you took to debug or research, and the final solution with metrics if possible.', '{"keywords": ["debugging", "research", "solution", "technical depth"], "concepts": ["STAR method", "Problem Solving"], "max_score": 100}'),
('What is Docker and why is it used?', 'DSA', 'EASY', 'DEVOPS', 'STARTUP', 'Docker is a containerization platform that packages an application and its dependencies into a single unit called a container, ensuring consistency across environments.', '{"keywords": ["containerization", "dependencies", "consistency", "isolation"], "concepts": ["DevOps", "Cloud"], "max_score": 100}'),
('What is the time complexity of searching in a Balanced Binary Search Tree?', 'DSA', 'EASY', 'SDE', 'ALL', 'The time complexity is O(log N) where N is the number of nodes, because the search space is halved at each step.', '{"keywords": ["O(log N)", "halving", "height", "nodes"], "concepts": ["Data Structures", "Trees"], "max_score": 100}'),
('Tell me about yourself.', 'HR', 'EASY', 'ALL', 'ALL', 'Follow the Past-Present-Future model: Summary of education/past experience, current role/projects, and why you are excited about this specific opportunity.', '{"keywords": ["Past-Present-Future", "education", "experience", "enthusiasm"], "concepts": ["HR Interview"], "max_score": 100}'),
('Explain the concept of Microservices architecture.', 'SYSTEM_DESIGN', 'MEDIUM', 'SDE', 'MNC', 'An approach where a large application is built as a suite of small, independent services communicating over lightweight protocols like HTTP/REST.', '{"keywords": ["independent", "suite", "decoupling", "REST"], "concepts": ["System Design", "Microservices"], "max_score": 100}'),
('What is the difference between SQL and NoSQL?', 'DSA', 'EASY', 'SDE', 'ALL', 'SQL databases are relational and use structured schemas. NoSQL databases are non-relational, flexible, and often scale horizontally better.', '{"keywords": ["relational", "schema", "flexible", "scaling"], "concepts": ["Databases"], "max_score": 100}'),
('Explain the ACID properties in a database.', 'DSA', 'MEDIUM', 'SDE', 'MNC', 'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure database transactions are processed reliably.', '{"keywords": ["Atomicity", "Consistency", "Isolation", "Durability"], "concepts": ["Databases", "Transactions"], "max_score": 100}'),
('How do you prioritize your tasks under a tight deadline?', 'BEHAVIORAL', 'MEDIUM', 'ALL', 'MNC', 'Discuss using tools like Jira or Eisenhower Matrix, communicating with stakeholders, and focusing on high-impact tasks first.', '{"keywords": ["prioritization", "communication", "impact", "deadlines"], "concepts": ["Time Management"], "max_score": 100}'),
('What is a Deadlock in an Operating System?', 'DSA', 'MEDIUM', 'SDE', 'MNC', 'A situation where a set of processes are blocked because each process is holding a resource and waiting for another resource held by another process.', '{"keywords": ["blocking", "resource", "circular wait", "mutex"], "concepts": ["Operating Systems"], "max_score": 100}'),
('Design a simple Chat System like WhatsApp.', 'SYSTEM_DESIGN', 'HARD', 'SDE', 'FAANG', 'Explain the use of WebSockets for real-time communication, a message database (Cassandra), and a presence service to track online status.', '{"keywords": ["WebSockets", "Cassandra", "real-time", "presence service"], "concepts": ["System Design", "Real-time"], "max_score": 100}'),
('What is the difference between Checked and Unchecked Exceptions in Java?', 'DSA', 'EASY', 'SDE', 'MNC', 'Checked exceptions must be handled or declared (try-catch or throws). Unchecked exceptions (RuntimeExceptions) don''t need explicit handling.', '{"keywords": ["RuntimeException", "try-catch", "throws", "Java"], "concepts": ["Programming Languages", "Java"], "max_score": 100}'),
('Where do you see yourself in five years?', 'HR', 'EASY', 'ALL', 'ALL', 'Mention career growth goals, gaining expertise in a specific technology, and potentially taking on leadership or mentoring roles within the company.', '{"keywords": ["growth", "expertise", "leadership", "mentoring"], "concepts": ["HR Interview"], "max_score": 100}'),
('Explain Dependency Injection.', 'DSA', 'MEDIUM', 'SDE', 'MNC', 'A design pattern where an object receives its dependencies from an external source rather than creating them itself, promoting decoupling.', '{"keywords": ["decoupling", "external source", "Inversion of Control", "Spring"], "concepts": ["Software Engineering", "Design Patterns"], "max_score": 100}'),
('How would you handle a situation where you realize you made a mistake that will delay a project?', 'BEHAVIORAL', 'MEDIUM', 'ALL', 'FAANG', 'Take ownership immediately, inform the manager/team, propose a solution or mitigation plan, and learn from the mistake to prevent it in the future.', '{"keywords": ["ownership", "communication", "mitigation", "learning"], "concepts": ["STAR method", "Accountability"], "max_score": 100}'),
('What is the difference between Load Balancer and Reverse Proxy?', 'SYSTEM_DESIGN', 'MEDIUM', 'DEVOPS', 'MNC', 'A load balancer distributes traffic across multiple servers. A reverse proxy sits in front of a web server and handles requests, security, and caching.', '{"keywords": ["distribution", "security", "caching", "edge"], "concepts": ["System Design", "Networking"], "max_score": 100}'),
('Explain "Sharding" in databases.', 'SYSTEM_DESIGN', 'HARD', 'SDE', 'STARTUP', 'Sharding is a method for distributing data across multiple machines based on a shard key to improve scalability and performance.', '{"keywords": ["shard key", "distribution", "scalability", "horizontal scaling"], "concepts": ["Databases", "System Design"], "max_score": 100}'),
('What is your ideal work environment?', 'HR', 'EASY', 'ALL', 'MNC', 'Mention values like collaboration, continuous learning, transparency, and a focus on delivering high-quality results.', '{"keywords": ["collaboration", "learning", "transparency", "quality"], "concepts": ["HR Interview"], "max_score": 100}'),
('What is a Lambda Expression in Java?', 'DSA', 'EASY', 'SDE', 'MNC', 'A short way to represent an anonymous function that can be passed around, introduced in Java 8 to support functional programming.', '{"keywords": ["anonymous function", "functional programming", "Java 8", "Stream API"], "concepts": ["Programming Languages", "Java"], "max_score": 100}'),
('Explain the difference between vertical and horizontal scaling.', 'SYSTEM_DESIGN', 'EASY', 'SDE', 'ALL', 'Vertical scaling means adding more power (CPU, RAM) to an existing machine. Horizontal scaling means adding more machines to the pool.', '{"keywords": ["CPU", "RAM", "pool", "machines"], "concepts": ["System Design", "Scalability"], "max_score": 100}');
